CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE app_users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, full_name VARCHAR(120) NOT NULL, role VARCHAR(20) NOT NULL DEFAULT 'USER' CHECK (role IN ('USER','ADMIN')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE accounts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), account_number VARCHAR(32) NOT NULL UNIQUE, owner_id UUID REFERENCES app_users(id), currency CHAR(3) NOT NULL DEFAULT 'INR', status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','FROZEN','CLOSED')), system_account BOOLEAN NOT NULL DEFAULT false, balance NUMERIC(19,2) NOT NULL DEFAULT 0 CHECK (system_account OR balance >= 0), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_accounts_owner ON accounts(owner_id);
CREATE TABLE ledger_transactions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), reference VARCHAR(40) NOT NULL UNIQUE, type VARCHAR(24) NOT NULL, status VARCHAR(16) NOT NULL CHECK (status IN ('POSTED','REVERSED')), description VARCHAR(500), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), reversed_transaction_id UUID UNIQUE REFERENCES ledger_transactions(id));
CREATE TABLE ledger_entries (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), transaction_id UUID NOT NULL REFERENCES ledger_transactions(id), account_id UUID NOT NULL REFERENCES accounts(id), direction VARCHAR(6) NOT NULL CHECK (direction IN ('DEBIT','CREDIT')), amount NUMERIC(19,2) NOT NULL CHECK (amount > 0), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_entries_account_date ON ledger_entries(account_id, created_at DESC);
CREATE INDEX idx_entries_transaction ON ledger_entries(transaction_id);
CREATE TABLE transfers (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), reference VARCHAR(40) NOT NULL UNIQUE, source_account_id UUID NOT NULL REFERENCES accounts(id), destination_account_id UUID NOT NULL REFERENCES accounts(id), amount NUMERIC(19,2) NOT NULL CHECK (amount > 0), currency CHAR(3) NOT NULL, description VARCHAR(500), status VARCHAR(16) NOT NULL CHECK (status IN ('COMPLETED','REVERSED')), ledger_transaction_id UUID NOT NULL REFERENCES ledger_transactions(id), initiated_by UUID NOT NULL REFERENCES app_users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), reversed_transfer_id UUID UNIQUE REFERENCES transfers(id));
CREATE INDEX idx_transfers_source_date ON transfers(source_account_id, created_at DESC);
CREATE INDEX idx_transfers_destination_date ON transfers(destination_account_id, created_at DESC);
CREATE TABLE idempotency_records (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES app_users(id), idempotency_key VARCHAR(128) NOT NULL, request_hash CHAR(64) NOT NULL, transfer_id UUID REFERENCES transfers(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(user_id,idempotency_key));
CREATE TABLE risk_assessments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), transaction_reference VARCHAR(40) NOT NULL, risk_score INTEGER NOT NULL CHECK (risk_score BETWEEN 0 AND 100), risk_level VARCHAR(8) NOT NULL CHECK (risk_level IN ('LOW','MEDIUM','HIGH')), triggered_rules JSONB NOT NULL DEFAULT '[]', explanation TEXT NOT NULL, review_status VARCHAR(20) NOT NULL DEFAULT 'PENDING' CHECK (review_status IN ('PENDING','APPROVED','ESCALATED','DISMISSED')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), reviewed_by UUID REFERENCES app_users(id), reviewed_at TIMESTAMPTZ);
CREATE INDEX idx_risk_review ON risk_assessments(review_status,created_at DESC);
CREATE TABLE audit_events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), actor_id UUID REFERENCES app_users(id), action VARCHAR(64) NOT NULL, resource_type VARCHAR(48) NOT NULL, resource_id VARCHAR(64), metadata JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_audit_created ON audit_events(created_at DESC);
CREATE TABLE reconciliation_runs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), status VARCHAR(16) NOT NULL CHECK (status IN ('CLEAN','DISCREPANCIES')), accounts_checked INTEGER NOT NULL, unbalanced_transactions INTEGER NOT NULL, balance_discrepancies INTEGER NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE reconciliation_discrepancies (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), run_id UUID NOT NULL REFERENCES reconciliation_runs(id), type VARCHAR(40) NOT NULL, resource_id VARCHAR(64), expected_value VARCHAR(128), actual_value VARCHAR(128), description TEXT NOT NULL);
CREATE TABLE simulated_settlements (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), external_reference VARCHAR(40) NOT NULL UNIQUE, transfer_reference VARCHAR(40), amount NUMERIC(19,2) NOT NULL CHECK(amount>0), currency CHAR(3) NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'SETTLED', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
